INSERT INTO pte_practice_items (id, task_type, payload) VALUES
('r-mcq-1', 'reading-mcq-single', '{"passage":"Urban beekeeping has grown in popularity across many cities over the past decade. Advocates argue that rooftop hives help pollinate community gardens and raise public awareness of declining bee populations. Critics, however, point out that untrained hobbyists can inadvertently spread diseases between colonies and that a high density of hives in one area may increase competition for the limited flowers found in cities.","question":"根据文章，反对城市养蜂的人主要担心什么？","options":["蜜蜂会袭击行人","缺乏经验的养蜂者可能传播疾病并造成蜂群间的资源竞争","屋顶蜂箱会损坏建筑结构","城市里完全没有花可供采蜜"],"correctIndex":1}'::jsonb),
('r-mcq-2', 'reading-mcq-single', '{"passage":"While remote work offers flexibility, several studies suggest that employees who work from home exclusively report feeling less connected to their teams than those who follow a hybrid schedule. Companies experimenting with mandatory in-office days say the goal is not to reduce flexibility but to preserve opportunities for spontaneous collaboration that video calls rarely replicate.","question":"公司要求每周固定进办公室的主要目的是什么？","options":["降低办公室租金","减少员工的工作灵活性","保留视频会议难以replicate的自发协作机会","监督员工的工作时长"],"correctIndex":2}'::jsonb),
('r-mcq-3', 'reading-mcq-single', '{"passage":"Vertical farming, which grows crops in stacked layers inside climate-controlled buildings, uses far less land and water than traditional agriculture. However, the high upfront cost of lighting and climate systems means that, so far, only high-value crops like leafy greens and herbs have proven commercially viable at scale.","question":"目前垂直农业主要种植哪类作物？为什么？","options":["主粮作物，因为产量最高","高价值的叶菜和香草，因为能抵消较高的前期成本","任何作物都可以，成本已经很低","只能种植观赏植物"],"correctIndex":1}'::jsonb),
('r-mcq-4', 'reading-mcq-single', '{"passage":"A recent survey of commuters found that those who read for pleasure during their commute reported lower stress levels than those who spent the same time checking work email. Researchers caution that the study cannot prove reading itself reduces stress, since people who choose to read may already be less anxious to begin with.","question":"研究人员对这项调查结果持什么态度？","options":["完全认同阅读能降低压力","认为查看工作邮件才是压力来源","谨慎，指出可能存在因果关系之外的解释","认为通勤方式与压力无关"],"correctIndex":2}'::jsonb),
('r-mcq-5', 'reading-mcq-single', '{"passage":"Museums that once discouraged photography now actively encourage visitors to share images on social media, viewing it as free publicity. Some curators worry, though, that visitors who spend their visit taking photos for others to see may engage less deeply with the artwork in front of them.","question":"一些策展人的担忧是什么？","options":["拍照会损坏艺术品","社交媒体宣传效果不好","游客可能因忙于拍照而减少对作品本身的投入","博物馆门票收入会下降"],"correctIndex":2}'::jsonb),
('r-mcq-6', 'reading-mcq-single', '{"passage":"Electric scooters have been praised for reducing short-distance car trips in cities, but emergency room data in several cities show a rise in scooter-related injuries, prompting some local governments to introduce speed limits and mandatory helmet rules in designated zones.","question":"一些地方政府采取了什么措施？","options":["全面禁止电动滑板车","在特定区域设置限速和强制头盔规定","取消所有交通规则","只允许游客使用滑板车"],"correctIndex":1}'::jsonb),
('r-mcq-7', 'reading-mcq-single', '{"passage":"Contrary to the assumption that multitasking boosts productivity, cognitive research indicates that switching rapidly between tasks incurs a measurable \"switching cost\" in time and accuracy, meaning that people who focus on one task at a time often complete more overall in a given period.","question":"认知研究发现了什么？","options":["多任务处理总是更高效","任务切换会产生时间和准确率上的代价","人类大脑无法处理任何切换","专注单一任务反而更慢"],"correctIndex":1}'::jsonb),
('r-mcq-8', 'reading-mcq-single', '{"passage":"A growing number of universities are offering micro-credentials — short, focused courses that certify a specific skill — as a complement to traditional degrees. Employers surveyed were divided: some valued the up-to-date, targeted skills these credentials signal, while others still weighted a full degree more heavily when making hiring decisions.","question":"雇主对\"微证书\"的态度如何？","options":["一致认为毫无价值","意见不一，有人看重其针对性技能，有人仍更看重完整学位","一致认为比学位更重要","完全没有被调查到"],"correctIndex":1}'::jsonb),
INSERT INTO pte_practice_items (id, task_type, payload) VALUES
('r-mcqm-1', 'reading-mcq-multiple', '{"passage":"City councils weighing whether to install more public drinking fountains cite several benefits: reduced plastic bottle waste, free access to water for low-income residents, and lower rates of dehydration-related emergency visits during heat waves. Some councils also note that fountains require ongoing maintenance and water-quality testing, which strains already limited budgets.","question":"根据文章，支持增设饮水台的理由有哪些？（选出所有正确答案）","options":["减少塑料瓶垃圾","为低收入居民提供免费饮水","降低热浪期间脱水就诊率","完全不需要维护成本"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-2', 'reading-mcq-multiple', '{"passage":"Proponents of a four-day work week argue it can reduce burnout, lower commuting-related emissions, and, in several pilot studies, maintain or even improve productivity. Skeptics counter that it may not suit every industry, particularly those requiring round-the-clock coverage such as healthcare.","question":"根据文章，支持四天工作制的理由有哪些？（选出所有正确答案）","options":["降低职业倦怠","减少通勤相关排放","在部分试点中维持或提升生产力","适用于所有行业，没有例外"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-3', 'reading-mcq-multiple', '{"passage":"Advocates for community gardens point to improved access to fresh produce, opportunities for neighbors to interact, and modest reductions in local food-transport emissions. Critics note that gardens can fail without a committed group of volunteers to maintain them long-term.","question":"根据文章，社区花园的好处包括哪些？（选出所有正确答案）","options":["改善新鲜农产品的获取","为邻里提供交流机会","略微降低本地食物运输排放","完全不需要志愿者维护"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-4', 'reading-mcq-multiple', '{"passage":"Digital note-taking apps offer searchable text, easy sharing, and automatic backup, which many students find convenient. Handwriting researchers, however, note that writing by hand has been linked to better recall of material in several studies, likely due to the slower, more deliberate encoding process it requires.","question":"根据文章，数字笔记应用的优势包括哪些？（选出所有正确答案）","options":["可搜索的文本","便于分享","自动备份","已被证明比手写记忆效果更好"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-5', 'reading-mcq-multiple', '{"passage":"Supporters of congestion pricing in city centers argue it reduces traffic jams, cuts air pollution, and can fund public transit improvements with the revenue collected. Opponents worry it disproportionately affects lower-income drivers who cannot easily switch to other forms of transport.","question":"根据文章，支持拥堵收费的理由有哪些？（选出所有正确答案）","options":["减少交通拥堵","降低空气污染","收入可用于改善公共交通","对所有收入群体的影响完全相同"],"correctIndexes":[0,1,2]}'::jsonb),
INSERT INTO pte_practice_items (id, task_type, payload) VALUES
('r-mcq-9', 'reading-mcq-single', '{"passage":"The Apollo program''s success depended heavily on early, unglamorous unmanned test flights that exposed critical flaws in heat shields and guidance software long before any astronaut boarded a capsule. Historians argue that this willingness to fail cheaply and often, rather than the more celebrated moon landing itself, was the program''s real engineering achievement.","question":"历史学家认为阿波罗计划真正的工程成就是什么？","options":["登月本身的画面","愿意通过廉价、频繁的无人测试及早暴露缺陷","拥有当时最先进的火箭发动机","完全没有经历过失败"],"correctIndex":1}'::jsonb),
('r-mcq-10', 'reading-mcq-single', '{"passage":"A common assumption is that older workers are less adaptable to new technology than younger colleagues. Longitudinal workplace data complicates this picture: while younger employees often pick up new software faster initially, older employees tend to close the gap within a few months and report higher long-term retention of the skills learned.","question":"纵向职场数据揭示了什么？","options":["年长员工完全无法学习新技术","年长员工初期学得快但很快遗忘","年轻员工初期上手更快，但年长员工几个月后追平且长期记忆更好","年龄与技能学习完全无关的结论尚无数据支持"],"correctIndex":2}'::jsonb),
('r-mcq-11', 'reading-mcq-single', '{"passage":"Traditional crop rotation, long dismissed by some as an outdated practice ill-suited to industrial farming, is being reconsidered as soil scientists document its role in naturally suppressing pests and replenishing nitrogen, potentially reducing the need for costly synthetic fertilizers.","question":"土壤科学家重新评估轮作制度的原因是什么？","options":["它能生产更高产量的单一作物","它有助于天然抑制病虫害并补充氮元素，可减少化肥使用","它比工业化农业更快","它完全不需要任何人力投入"],"correctIndex":1}'::jsonb),
('r-mcq-12', 'reading-mcq-single', '{"passage":"Public speaking anxiety is often attributed to fear of judgment, but cognitive behavioral researchers note that a significant portion of the discomfort stems from an exaggerated sense of how much an audience actually notices small mistakes, a phenomenon closely related to what psychologists call the \"spotlight effect.\"","question":"认知行为研究者认为公开演讲焦虑的部分原因是什么？","options":["听众普遍非常严厉","人们高估了听众对自己小失误的关注程度，即\"聚光灯效应\"","演讲者天生缺乏语言能力","焦虑与听众人数完全无关"],"correctIndex":1}'::jsonb),
('r-mcq-13', 'reading-mcq-single', '{"passage":"Streaming services initially promised to reduce piracy by making legal content more convenient than illegal downloads. However, as the number of competing subscription platforms has grown, some analysts note that fragmented content libraries may be reviving the very inconvenience that once drove consumers toward piracy.","question":"一些分析师担忧什么？","options":["流媒体平台数量太少","订阅平台数量增多导致内容分散，可能重新造成不便，助长盗版","所有观众都已完全放弃合法平台","盗版问题已经彻底消失"],"correctIndex":1}'::jsonb),
('r-mcq-14', 'reading-mcq-single', '{"passage":"Excavations at a Bronze Age settlement revealed grain silos far larger than the local population could have needed, leading archaeologists to propose that the community functioned as a regional trading hub rather than a purely self-sufficient village.","question":"考古学家据此提出了什么假设？","options":["这个聚落人口远超预期","该聚落可能是区域贸易枢纽，而非单纯自给自足的村庄","粮仓的规模纯属建筑失误","这个聚落从未储存过粮食"],"correctIndex":1}'::jsonb),
('r-mcq-15', 'reading-mcq-single', '{"passage":"Noise-cancelling headphones work by generating a sound wave that is the inverse of ambient noise, effectively cancelling it out before it reaches the ear. This technique is most effective against low, constant frequencies like engine hum, but far less effective against sudden, unpredictable sounds such as a dog barking.","question":"降噪耳机对哪种声音效果较差？","options":["低沉持续的引擎噪音","突然且不可预测的声音，例如狗叫","所有类型的声音都同样有效","完全没有降噪效果"],"correctIndex":1}'::jsonb),
('r-mcq-16', 'reading-mcq-single', '{"passage":"Many nutrition guidelines have shifted away from labeling individual foods as simply \"good\" or \"bad,\" instead emphasizing overall dietary patterns. This shift followed research suggesting that focusing on single nutrients or foods often leads people to compensate elsewhere in ways that cancel out any benefit.","question":"营养指南为什么转向强调整体饮食模式？","options":["单一食物完全不再重要","过度关注单一营养素或食物容易导致其他方面的补偿行为抵消收益","这样可以让食品公司更容易营销","整体模式比单一食物更便宜"],"correctIndex":1}'::jsonb),
('r-mcq-17', 'reading-mcq-single', '{"passage":"Second-language acquisition research increasingly emphasizes comprehensible input — exposure to language slightly above a learner''s current level — over rote grammar drills. Advocates argue this mirrors how children acquire their first language, though critics note that adult learners may still benefit from some explicit grammar instruction.","question":"批评者对\"可理解输入\"理论提出了什么保留意见？","options":["儿童完全不需要语言输入","成年学习者可能仍然需要一些明确的语法讲解","这一理论已被完全推翻","语法练习对任何人都毫无用处"],"correctIndex":1}'::jsonb),
('r-mcqm-6', 'reading-mcq-multiple', '{"passage":"Advocates for open-plan offices argue they encourage spontaneous collaboration and reduce construction costs compared with individual offices. However, a growing body of research links open-plan layouts to higher noise levels and, somewhat counterintuitively, fewer face-to-face conversations as employees retreat to messaging apps to avoid being overheard.","question":"根据文章，开放式办公室存在哪些问题？（选出所有正确答案）","options":["噪音水平更高","面对面交流反而减少","建造成本更低","完全不影响员工的沟通方式"],"correctIndexes":[0,1]}'::jsonb),
('r-mcqm-7', 'reading-mcq-multiple', '{"passage":"Proponents of urban composting programs highlight reduced landfill methane emissions, nutrient-rich soil for community gardens, and lower municipal waste-hauling costs. Skeptics note that poorly managed compost bins can attract pests and produce unpleasant odors in dense residential areas.","question":"根据文章，城市堆肥计划的支持者提到了哪些好处？（选出所有正确答案）","options":["减少垃圾填埋场的甲烷排放","为社区花园提供富含营养的土壤","降低市政垃圾清运成本","完全不会产生任何异味"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-8', 'reading-mcq-multiple', '{"passage":"Studies of bilingual children report cognitive advantages including improved task-switching ability and better performance on tests requiring the suppression of irrelevant information. Researchers stress, however, that these advantages are modest and should not be mistaken for a general boost in overall intelligence.","question":"根据文章，研究发现双语儿童具有哪些认知优势？（选出所有正确答案）","options":["更好的任务切换能力","更擅长抑制无关信息的干扰","整体智力显著高于单语儿童","这些优势幅度较小，并非整体智力提升"],"correctIndexes":[0,1]}'::jsonb),
('r-mcqm-9', 'reading-mcq-multiple', '{"passage":"Supporters of carbon capture technology point to its potential to allow existing power plants to keep operating while cutting emissions, and to create a new industry around underground storage. Critics counter that the technology remains expensive at scale and may delay investment in renewable alternatives.","question":"根据文章，碳捕获技术的支持者提出了哪些理由？（选出所有正确答案）","options":["允许现有电厂继续运营同时减少排放","催生地下封存相关的新产业","目前在大规模应用中成本低廉","完全不会影响可再生能源的投资"],"correctIndexes":[0,1]}'::jsonb),
('r-mcqm-10', 'reading-mcq-multiple', '{"passage":"Proponents of school uniforms argue they reduce visible economic disparity among students, simplify morning routines for families, and, according to some surveys, modestly reduce bullying related to clothing choices. Opponents argue uniforms suppress individual expression without solid evidence of academic benefit.","question":"根据文章，校服支持者提出的理由包括哪些？（选出所有正确答案）","options":["减少学生间可见的经济差距","简化家庭的晨间准备流程","有调查显示可适度减少与穿着相关的欺凌","已被证实能显著提高学习成绩"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-11', 'reading-mcq-multiple', '{"passage":"Wildlife corridors connecting fragmented habitats have been shown to increase genetic diversity within isolated animal populations and reduce roadkill by guiding animals away from highways. Building them, however, often requires costly land acquisition and years of negotiation with multiple landowners.","question":"根据文章，野生动物廊道带来的好处有哪些？（选出所有正确答案）","options":["增加孤立种群的遗传多样性","通过引导动物远离公路减少路杀","建设成本几乎为零","不需要与任何土地所有者协商"],"correctIndexes":[0,1]}'::jsonb),
('r-mcqm-12', 'reading-mcq-multiple', '{"passage":"Defenders of open-source software argue it allows for greater transparency, faster identification of security vulnerabilities through community review, and freedom from vendor lock-in. Detractors note that ongoing maintenance can suffer without a company''s financial backing, and support can be less predictable than commercial software.","question":"根据文章，开源软件的支持者提出的优势包括哪些？（选出所有正确答案）","options":["更高的透明度","通过社区审查更快发现安全漏洞","不受单一供应商锁定","维护和支持永远比商业软件更稳定"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-13', 'reading-mcq-multiple', '{"passage":"Researchers evaluating meditation apps found modest improvements in self-reported stress and sleep quality among regular users, alongside increased daily mindfulness practice. They caution the apps are not a substitute for treatment of clinical anxiety or depression.","question":"根据文章，冥想应用的常规使用者报告了哪些变化？（选出所有正确答案）","options":["自评压力有所改善","睡眠质量有所改善","日常正念练习增加","可以完全替代临床焦虑症的治疗"],"correctIndexes":[0,1,2]}'::jsonb),
('r-mcqm-14', 'reading-mcq-multiple', '{"passage":"Proponents of nuclear power point to its low operational carbon emissions and ability to provide constant baseload electricity regardless of weather. Opponents raise concerns about long-term radioactive waste storage and the high upfront capital cost of building new plants.","question":"根据文章，反对核电的人提出了哪些担忧？（选出所有正确答案）","options":["长期放射性废物的储存问题","新建电厂的前期资本成本高昂","核电的运营碳排放极高","核电无法提供稳定的基载电力"],"correctIndexes":[0,1]}'::jsonb),
('r-mcqm-15', 'reading-mcq-multiple', '{"passage":"Supporters of telehealth expansion cite improved access for patients in rural areas, reduced travel time and cost, and the ability to monitor chronic conditions remotely between visits. Some physicians note that certain diagnoses still require hands-on examination that video consultations cannot replace.","question":"根据文章，远程医疗的支持者提出了哪些理由？（选出所有正确答案）","options":["改善农村地区患者的医疗可及性","减少患者的出行时间和费用","能够在就诊间隔远程监测慢性病","可以完全取代所有需要手动检查的诊断"],"correctIndexes":[0,1,2]}'::jsonb),
('r-reorder-6', 'reading-reorder', '{"paragraphs":["To address this, several hospitals have introduced dedicated interpreter services available around the clock.","Language barriers between patients and medical staff have been linked to higher rates of misdiagnosis and medication errors.","Without a shared language, subtle but clinically important details are often lost during consultations.","Early data suggests that hospitals using these services see fewer repeat visits caused by miscommunication."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-7', 'reading-reorder', '{"paragraphs":["As a result, some record labels have begun releasing albums exclusively on vinyl before making them available digitally.","Vinyl record sales have risen for over a decade even as streaming dominates how most people listen to music.","Collectors and younger listeners alike cite the physical ritual and tactile packaging as part of vinyl''s appeal.","Whether this trend will continue to grow or has already reached its natural ceiling remains a matter of debate among industry analysts."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-8', 'reading-reorder', '{"paragraphs":["This discrepancy prompted researchers to examine whether sample selection, rather than diet itself, explained the conflicting results.","Nutrition studies on the health effects of a single food item frequently produce contradictory findings from one year to the next.","Participants who volunteer for such studies often differ systematically from the general population in income, education, and existing health habits.","Subsequent studies that controlled more carefully for these factors found far smaller effects than the original headlines suggested."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-9', 'reading-reorder', '{"paragraphs":["In response, several airlines began experimenting with dynamic boarding groups assigned only minutes before departure.","Boarding a full passenger aircraft efficiently has remained a surprisingly difficult logistical problem for decades.","Fixed boarding-group systems often lead to bottlenecks in the aisle as passengers all try to store luggage at once.","Early trials of the dynamic system report modest reductions in average boarding time, though results vary by aircraft size."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-10', 'reading-reorder', '{"paragraphs":["Consequently, conservationists have begun releasing captive-bred individuals into carefully selected, predator-free habitats.","Several amphibian species have suffered dramatic population declines linked to a fast-spreading fungal disease.","The fungus disrupts the skin function amphibians rely on for breathing and water regulation, often proving fatal.","Early monitoring of the released populations shows encouraging survival rates, though long-term success is not yet guaranteed."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-11', 'reading-reorder', '{"paragraphs":["To reduce this risk, financial regulators in several countries now require lenders to verify income more rigorously before approving loans.","In the years leading up to the global financial crisis, many mortgage lenders approved loans with minimal verification of a borrower''s actual income.","This practice contributed to a sharp rise in loans that borrowers were ultimately unable to repay.","Critics argue the stricter rules, while safer, have also made it harder for some creditworthy first-time buyers to qualify."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-12', 'reading-reorder', '{"paragraphs":["This led some theaters to introduce dynamic pricing, charging more for popular showtimes and less for weekday matinees.","Cinema attendance has fluctuated considerably since the widespread adoption of home streaming services.","Industry data shows that ticket prices had remained largely flat for years despite rising operating costs.","Early results suggest dynamic pricing has modestly improved attendance during previously under-booked time slots."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-13', 'reading-reorder', '{"paragraphs":["To address this shortfall, several universities have partnered directly with local manufacturers to design apprenticeship-style courses.","Employers in advanced manufacturing frequently report difficulty finding technicians with the specific skills their machinery requires.","Traditional engineering degrees, while rigorous, often do not cover the exact equipment used on a specific factory floor.","Graduates of the new partnership programs report faster hiring and higher starting wages than peers from conventional programs."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-14', 'reading-reorder', '{"paragraphs":["As a result, several national parks now use timed-entry ticketing to spread visitor arrivals more evenly throughout the day.","Some of the world''s most popular national parks have struggled with overcrowding during peak tourist seasons.","Overcrowding has been linked to trail erosion, wildlife disturbance, and a diminished experience for visitors themselves.","Visitor surveys since the introduction of timed entry report higher satisfaction despite the added step of advance booking."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-reorder-15', 'reading-reorder', '{"paragraphs":["In response, some cities have begun offering free transit passes during declared air-quality emergencies.","Air pollution in several major cities spikes sharply during specific weather conditions that trap emissions close to the ground.","During these episodes, hospitals typically report a measurable rise in respiratory-related emergency visits.","Preliminary data suggests the free-transit measure modestly reduces car use during the affected days, though the effect fades once passes expire."],"correctOrder":[1,2,0,3]}'::jsonb),
('r-fillblank-6', 'reading-fill-blanks-drag', '{"textSegments":["Volcanic soil is prized by farmers for its "," mineral content, which can make surrounding regions remarkably "," for agriculture despite the "," risk posed by future eruptions."],"blankCount":3,"wordBank":["rich","fertile","ongoing","poor","temporary"],"correctAnswers":["rich","fertile","ongoing"]}'::jsonb),
('r-fillblank-7', 'reading-fill-blanks-drag', '{"textSegments":["Urban planners increasingly favor mixed-use "," that combine housing, shops, and offices within walking ",", arguing this reduces the daily reliance on "," transport."],"blankCount":3,"wordBank":["zoning","distance","private","height","public"],"correctAnswers":["zoning","distance","private"]}'::jsonb),
