('w-essay-8', 'writing-essay', '{"prompt":"Some people believe that children should begin learning a foreign language as early as possible, while others think it is better to focus first on their native language. Discuss both views and give your own opinion.","minWords":200,"maxWords":300}'::jsonb),
('w-essay-9', 'writing-essay', '{"prompt":"Some believe that space exploration is a worthwhile use of public funds, while others argue that the money would be better spent addressing problems on Earth. Discuss both views and give your own opinion.","minWords":200,"maxWords":300}'::jsonb),
